-- Optional, private Daily Alignment and Weekly Review. Separate from the
-- coach-visible weekly_checkins table. No score or entry is generated by visits.
-- Apply in a test project first. Safe to rerun. No existing records are changed.

create or replace function public.alignment_is_member()
returns boolean language sql stable security definer set search_path = public
as $$
  select exists (select 1 from auth.users u where u.id = auth.uid() and not coalesce(u.is_anonymous, true));
$$;
revoke all on function public.alignment_is_member() from public, anon, service_role;
grant execute on function public.alignment_is_member() to authenticated;

create or replace function public.alignment_valid_timezone(zone text)
returns boolean language sql stable set search_path = public
as $$
  select (zone = 'UTC' or position('/' in zone) > 0)
    and exists (select 1 from pg_timezone_names where name = zone);
$$;
revoke all on function public.alignment_valid_timezone(text) from public, anon, service_role;
grant execute on function public.alignment_valid_timezone(text) to authenticated;

create table if not exists public.daily_alignments (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.profiles(id) on delete cascade,
  entry_date date not null,
  timezone text not null default 'UTC' check (length(timezone) <= 100 and public.alignment_valid_timezone(timezone)),
  presence_done boolean,
  priority text check (length(priority) <= 500),
  goal_id uuid references public.goals(id) on delete set null,
  value text check (length(value) <= 80),
  wellbeing_action text check (length(wellbeing_action) <= 300),
  evening_note text check (length(evening_note) <= 1000),
  wellbeing text check (wellbeing in ('yes', 'partly', 'not_today')),
  meaningful_action text check (meaningful_action in ('yes', 'partly', 'not_today')),
  participation text check (participation in ('yes', 'partly', 'not_today')),
  values_choice text check (values_choice in ('yes', 'partly', 'not_today', 'not_needed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (client_id, entry_date)
);
create table if not exists public.alignment_weekly_reviews (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.profiles(id) on delete cascade,
  week_start date not null check (extract(isodow from week_start) = 1),
  timezone text not null default 'UTC' check (length(timezone) <= 100 and public.alignment_valid_timezone(timezone)),
  helped text check (length(helped) <= 1000),
  adjustment text check (length(adjustment) <= 1000),
  next_priority text check (length(next_priority) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (client_id, week_start)
);

-- A linked CLEAR goal must belong to the same member even if the caller is
-- a coach who can read another member's goal through the old goals policies.
create or replace function public.check_alignment_goal_owner()
returns trigger language plpgsql set search_path = public
as $$
begin
  if new.goal_id is not null and not exists (
    select 1 from public.goals g where g.id = new.goal_id and g.client_id = new.client_id
  ) then raise exception 'Choose one of your own goals' using errcode = '23514'; end if;
  return new;
end;
$$;
revoke all on function public.check_alignment_goal_owner() from public, anon, service_role;
drop trigger if exists alignment_goal_owner on public.daily_alignments;
create trigger alignment_goal_owner before insert or update on public.daily_alignments
  for each row execute function public.check_alignment_goal_owner();
drop trigger if exists daily_alignments_updated_at on public.daily_alignments;
create trigger daily_alignments_updated_at before update on public.daily_alignments
  for each row execute function public.set_updated_at();
drop trigger if exists alignment_weekly_reviews_updated_at on public.alignment_weekly_reviews;
create trigger alignment_weekly_reviews_updated_at before update on public.alignment_weekly_reviews
  for each row execute function public.set_updated_at();

alter table public.daily_alignments enable row level security;
alter table public.alignment_weekly_reviews enable row level security;
revoke all on public.daily_alignments, public.alignment_weekly_reviews from public, anon, service_role;
grant select, insert, update, delete on public.daily_alignments, public.alignment_weekly_reviews to authenticated;
drop policy if exists "daily alignment: member owns private record" on public.daily_alignments;
create policy "daily alignment: member owns private record" on public.daily_alignments
  for all to authenticated
  using (client_id = auth.uid() and public.alignment_is_member())
  with check (client_id = auth.uid() and public.alignment_is_member());
drop policy if exists "weekly alignment: member owns private record" on public.alignment_weekly_reviews;
create policy "weekly alignment: member owns private record" on public.alignment_weekly_reviews
  for all to authenticated
  using (client_id = auth.uid() and public.alignment_is_member())
  with check (client_id = auth.uid() and public.alignment_is_member());
-- Deliberately no coach/admin policy, analytics trigger, sharing or public RPC.
